window.CODE = Object.assign(window.CODE || {}, {"ch05/api.py":"\"\"\"City Clinic Helpdesk API with FastAPI.\n\nEndpoints\n  GET  /health        is the service up?\n  POST /ask           one question in, one answer out (JSON)\n  POST /ask/stream    the answer streamed word by word (Server-Sent Events)\n  POST /summarise     upload a .txt file (e.g. a discharge note) and get a short summary\n\nRun:  pip install fastapi uvicorn python-multipart\n      uvicorn api:app --reload\nThen open http://127.0.0.1:8000/docs to try every endpoint in the browser (Swagger UI).\n\"\"\"\nimport json\nimport logging\nimport sys\nimport time\nimport uuid\nfrom pathlib import Path\nfrom typing import Literal\n\nfrom fastapi import FastAPI, File, HTTPException, Request, UploadFile\nfrom fastapi.responses import StreamingResponse\nfrom pydantic import BaseModel, Field\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nimport llm  # noqa: E402  (imported after the path fix)\n\nlogging.basicConfig(level=logging.INFO, format=\"%(asctime)s %(levelname)s %(message)s\")\nlog = logging.getLogger(\"helpdesk\")\n\nSYSTEM = (\"You are the City Clinic helpdesk. Answer briefly and politely. You do not give medical advice; \"\n          \"for emergencies tell the patient to go to Emergency or call 108.\")\nMAX_UPLOAD_BYTES = 200_000\n\napp = FastAPI(title=\"City Clinic Helpdesk API\", version=\"1.0\")\n\n\n# ---------- request and response shapes (Pydantic validates every request for us)\nclass Message(BaseModel):\n    role: Literal[\"user\", \"assistant\"]\n    content: str = Field(max_length=4000)\n\n\nclass AskRequest(BaseModel):\n    question: str = Field(min_length=1, max_length=1000, examples=[\"What are the OPD timings?\"])\n    history: list[Message] = Field(default=[], max_length=20)\n\n\nclass AskResponse(BaseModel):\n    answer: str\n    input_tokens: int\n    output_tokens: int\n    model: str\n\n\n# ---------- log every request with an id and how long it took\n@app.middleware(\"http\")\nasync def log_requests(request: Request, call_next):\n    request_id = uuid.uuid4().hex[:8]\n    start = time.perf_counter()\n    response = await call_next(request)\n    response.headers[\"X-Request-ID\"] = request_id\n    log.info(\"%s %s %s %d %.0fms\", request_id, request.method, request.url.path,\n             response.status_code, (time.perf_counter() - start) * 1000)\n    return response\n\n\n@app.get(\"/health\")\ndef health() -> dict:\n    return {\"status\": \"ok\", \"provider\": llm.PROVIDER, \"model\": llm.MODELS[llm.PROVIDER]}\n\n\n@app.post(\"/ask\", response_model=AskResponse)\ndef ask(req: AskRequest) -> AskResponse:\n    try:\n        r = llm.chat(req.question, system=SYSTEM, history=[m.model_dump() for m in req.history])\n    except Exception as exc:                        # never show raw provider errors to users\n        log.exception(\"model call failed\")\n        raise HTTPException(503, \"The assistant is busy. Please try again in a minute.\") from exc\n    return AskResponse(answer=r[\"text\"], input_tokens=r[\"input_tokens\"],\n                       output_tokens=r[\"output_tokens\"], model=r[\"model\"])\n\n\n@app.post(\"/ask/stream\")\ndef ask_stream(req: AskRequest) -> StreamingResponse:\n    \"\"\"Server-Sent Events: each event is a line 'data: {...}' followed by a blank line.\"\"\"\n    def events():\n        try:\n            for chunk in llm.stream(req.question, system=SYSTEM, history=[m.model_dump() for m in req.history]):\n                yield f\"data: {json.dumps({'text': chunk})}\\n\\n\"\n        except Exception:\n            log.exception(\"stream failed\")\n            yield f\"data: {json.dumps({'error': 'The assistant is busy. Please try again.'})}\\n\\n\"\n        yield \"data: [DONE]\\n\\n\"\n    return StreamingResponse(events(), media_type=\"text/event-stream\")\n\n\n@app.post(\"/summarise\")\nasync def summarise(file: UploadFile = File(...)) -> dict:\n    if not (file.filename or \"\").lower().endswith(\".txt\"):\n        raise HTTPException(415, \"Please upload a .txt file.\")\n    data = await file.read()\n    if len(data) > MAX_UPLOAD_BYTES:\n        raise HTTPException(413, f\"File too large. Limit is {MAX_UPLOAD_BYTES // 1000} KB.\")\n    text = data.decode(\"utf-8\", errors=\"replace\")\n    r = llm.chat(\"Summarise this clinic document for a patient in 3 short bullet points. \"\n                 \"Do not add medical advice that is not in the text.\\n\\n\" + text, max_tokens=300)\n    return {\"filename\": file.filename, \"summary\": r[\"text\"], \"characters\": len(text)}\n","ch05/app_gradio.py":"\"\"\"A shareable chat demo with Gradio. It calls the model directly, so it can run on its own,\nfor example on Hugging Face Spaces.\n\nRun locally:   pip install gradio\n               python app_gradio.py          (add share=True to launch() for a temporary public link)\nOn Hugging Face Spaces: create a Gradio Space, upload this file as app.py together with ../llm.py\nand a requirements.txt, and add your API key under Settings -> Variables and secrets.\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nimport gradio as gr\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom llm import stream  # noqa: E402\n\nSYSTEM = (\"You are the City Clinic helpdesk. Answer briefly and politely. You do not give medical advice; \"\n          \"for emergencies tell the patient to go to Emergency or call 108.\")\n\n\ndef respond(message: str, history: list):\n    \"\"\"Gradio passes the new message and the earlier turns as [{'role', 'content'}, ...].\"\"\"\n    past = [{\"role\": m[\"role\"], \"content\": m[\"content\"]} for m in history[-10:]]\n    text = \"\"\n    for chunk in stream(message, system=SYSTEM, history=past):\n        text += chunk\n        yield text                                    # yielding partial text makes it stream\n\n\ndemo = gr.ChatInterface(\n    respond,\n    title=\"City Clinic Helpdesk\",\n    description=\"Example app with made-up data. Not medical advice.\",\n    examples=[\"What are the OPD timings?\", \"Which departments do you have?\"],\n)\n\nif __name__ == \"__main__\":\n    demo.launch()\n","ch05/app_streamlit.py":"\"\"\"A streaming chat UI in Streamlit that talks to the FastAPI backend (api.py).\n\nRun:  first start the API:   uvicorn api:app\n      then, in a second terminal:   pip install streamlit httpx\n                                    streamlit run app_streamlit.py\n\"\"\"\nimport json\nimport os\n\nimport httpx\nimport streamlit as st\n\nAPI_URL = os.getenv(\"HELPDESK_API\", \"http://127.0.0.1:8000\")\n\nst.set_page_config(page_title=\"City Clinic Helpdesk\", page_icon=\"🏥\")\nst.title(\"City Clinic Helpdesk\")\nst.caption(\"Example app. Made-up clinic. Not medical advice.\")\n\n# st.session_state survives each rerun of the script, so it holds the conversation.\nif \"messages\" not in st.session_state:\n    st.session_state.messages = []\n\nfor m in st.session_state.messages:                      # redraw the conversation so far\n    with st.chat_message(m[\"role\"]):\n        st.markdown(m[\"content\"])\n\n\ndef stream_answer(question: str, history: list):\n    \"\"\"Read Server-Sent Events from /ask/stream and yield text as it arrives.\"\"\"\n    with httpx.stream(\"POST\", f\"{API_URL}/ask/stream\", json={\"question\": question, \"history\": history},\n                      timeout=60) as response:\n        for line in response.iter_lines():\n            if not line.startswith(\"data: \") or line == \"data: [DONE]\":\n                continue\n            event = json.loads(line[6:])\n            yield event.get(\"text\") or event.get(\"error\", \"\")\n\n\nif question := st.chat_input(\"Ask about doctors, timings or appointments\"):\n    history = st.session_state.messages[-10:]            # send only recent turns (Chapter 2)\n    st.session_state.messages.append({\"role\": \"user\", \"content\": question})\n    with st.chat_message(\"user\"):\n        st.markdown(question)\n    with st.chat_message(\"assistant\"):\n        try:\n            answer = st.write_stream(stream_answer(question, history))   # shows text as it streams\n        except httpx.HTTPError:\n            answer = \"The helpdesk service is not reachable. Is `uvicorn api:app` running?\"\n            st.error(answer)\n    st.session_state.messages.append({\"role\": \"assistant\", \"content\": answer})\n","ch05/test_api.py":"\"\"\"Automated tests for api.py. They replace the model with a fake, so they run in a second,\ncost nothing and need no API key. Run them before every change.\n\nRun:  pip install pytest httpx\n      pytest -q test_api.py\n\"\"\"\nimport json\n\nimport pytest\nfrom fastapi.testclient import TestClient\n\nimport api\n\n\n@pytest.fixture\ndef client(monkeypatch):\n    def fake_chat(user, system=None, history=None, **kw):\n        return {\"text\": f\"echo: {user}\", \"input_tokens\": 10, \"output_tokens\": 3, \"model\": \"fake\"}\n\n    def fake_stream(user, system=None, history=None, **kw):\n        yield from [\"Hello\", \" from\", \" the clinic\"]\n\n    monkeypatch.setattr(api.llm, \"chat\", fake_chat)\n    monkeypatch.setattr(api.llm, \"stream\", fake_stream)\n    return TestClient(api.app)\n\n\ndef test_health(client):\n    assert client.get(\"/health\").json()[\"status\"] == \"ok\"\n\n\ndef test_ask(client):\n    r = client.post(\"/ask\", json={\"question\": \"OPD timings?\"})\n    assert r.status_code == 200\n    assert r.json()[\"answer\"] == \"echo: OPD timings?\"\n    assert \"X-Request-ID\" in r.headers\n\n\ndef test_empty_question_is_rejected(client):\n    assert client.post(\"/ask\", json={\"question\": \"\"}).status_code == 422\n\n\ndef test_model_failure_gives_friendly_503(client, monkeypatch):\n    def broken(*a, **kw):\n        raise RuntimeError(\"provider down\")\n    monkeypatch.setattr(api.llm, \"chat\", broken)\n    r = client.post(\"/ask\", json={\"question\": \"hi\"})\n    assert r.status_code == 503 and \"busy\" in r.json()[\"detail\"]\n\n\ndef test_stream(client):\n    with client.stream(\"POST\", \"/ask/stream\", json={\"question\": \"hi\"}) as r:\n        lines = [l for l in r.iter_lines() if l.startswith(\"data: \")]\n    texts = [json.loads(l[6:])[\"text\"] for l in lines if l != \"data: [DONE]\"]\n    assert \"\".join(texts) == \"Hello from the clinic\" and lines[-1] == \"data: [DONE]\"\n\n\ndef test_upload_rules(client):\n    assert client.post(\"/summarise\", files={\"file\": (\"note.pdf\", b\"x\")}).status_code == 415\n    big = b\"a\" * (api.MAX_UPLOAD_BYTES + 1)\n    assert client.post(\"/summarise\", files={\"file\": (\"note.txt\", big)}).status_code == 413\n    ok = client.post(\"/summarise\", files={\"file\": (\"note.txt\", b\"Discharged after 2 days.\")})\n    assert ok.status_code == 200 and ok.json()[\"characters\"] == 24\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
